<?php
// Regenerates nfo_golden.json from the real PHP classes (no app bootstrap) and PHP's bundled
// libmagic. After rust/porting/php-ref-setup.sh:
//   php generate_nfo_golden.php <php-final checkout> > nfo_golden.json
//
// isNFO writes the bytes to a file for libmagic through Laravel's File facade, which needs the
// app. Its steps are run here in the same order instead, with finfo_buffer in place of the file.
declare(strict_types=1);

$ref = $argv[1];
require $ref.'/vendor/autoload.php';

use App\Services\NfoService;
use App\Services\Nzb\NzbParserService;

$service = (new ReflectionClass(NfoService::class))->newInstanceWithoutConstructor();
$property = static fn (string $name): string => (new ReflectionProperty(NfoService::class, $name))->getValue($service);
$method = static fn (string $name): Closure => (new ReflectionMethod(NfoService::class, $name))->getClosure($service);
$detectBinary = $method('detectBinaryFormat');
$validate = $method('validateNfoContent');
$nonNfo = $property('_nonNfoHeaderRegex');
$textFile = $property('_textFileRegex');
$binaryFile = $property('_binaryFileRegex');
$binaryChars = $property('_binaryCharsRegex');
$finfo = finfo_open(FILEINFO_RAW);

$isNfo = static function (string $data) use ($detectBinary, $validate, $nonNfo, $textFile, $binaryFile, $binaryChars, $finfo): bool {
    if ($data === '' || strlen($data) >= 65535 || strlen($data) < 12) {
        return false;
    }
    if (preg_match($nonNfo, $data) || $detectBinary($data)) {
        return false;
    }
    $result = finfo_buffer($finfo, $data);
    if (empty($result)) {
        throw new RuntimeException('libmagic gave no answer');
    }
    $isNfo = false;
    if (preg_match($textFile, $result)) {
        $isNfo = true;
    } elseif (preg_match($binaryFile, $result) || preg_match($binaryChars, $data)) {
        $isNfo = false;
    }

    return $isNfo ? $validate($data) : false;
};

$scene = <<<'NFO'
           ___________________________________________
          |                                           |
          |     Some.Movie.2021.2160p.BluRay.x265     |
          |___________________________________________|

  Release Date ....: 2021-05-01
  Source ..........: UHD BluRay
  Video ...........: HEVC 10bit HDR
  Audio ...........: English TrueHD Atmos 7.1
  Subtitles .......: English, French
  IMDB ............: https://www.imdb.com/title/tt0000001/

  Greets to all the groups keeping the scene alive.
NFO;
$art = "\xdb\xdb\xdb\xdb\xb2\xb2\xb1\xb0  GROUP PRESENTS  \xb0\xb1\xb2\xb2\xdb\xdb\xdb\xdb\r\n"
    ."\xc9\xcd\xcd\xcd\xcd\xcd\xcd\xcd\xcd\xcd\xcd\xcd\xcd\xbb\r\n"
    ."\xba Title....: Some Show S01E01 \xba\r\n"
    ."\xba Source...: WEB-DL 1080p     \xba\r\n"
    ."\xba Size.....: 2.1 GB           \xba\r\n"
    ."\xc8\xcd\xcd\xcd\xcd\xcd\xcd\xcd\xcd\xcd\xcd\xcd\xcd\xbc\r\n";
$plain = 'This is just a short note about nothing in particular, written for a friend at home.';
$fields = "Name: Something\nKind: Other thing\nWhen: Later on\nWhere: Somewhere\nWho: Someone\nWhy: No reason at all here\n";

$samples = [
    'scene' => $scene,
    'scene crlf' => str_replace("\n", "\r\n", $scene),
    'cp437 art' => $art,
    'cp437 art with eof' => $art."\x1a",
    'scene with trailing nuls' => $scene."\0\0\0",
    'scene utf8' => str_replace('French', "Fran\xc3\xa7ais", $scene),
    'scene utf8 bom' => "\xef\xbb\xbf".$scene,
    'scene latin1' => str_replace('French', "Fran\xe7ais", $scene),
    'scene utf16le bom' => "\xff\xfe".mb_convert_encoding($scene, 'UTF-16LE', 'UTF-8'),
    'scene utf7 prefix' => '+/v8'.$scene,
    'scene with control char' => "\x01".$scene,
    'scene with nul inside' => substr($scene, 0, 40)."\0".substr($scene, 40),
    'plain prose' => $plain,
    'fields only' => $fields,
    'rules and url' => "------------------------------\nvisit www.example.org for more of this stuff today\n",
    'media ids' => "Look it up on thetvdb.com or imdb.com when you get a moment please friend\n",
    'too short' => 'tiny nfo',
    'under fifty' => 'release group source codec video',
    'few words' => str_repeat('== 12345 67890 ', 6),
    'mostly binary' => str_repeat("\x80\x81\x82\x83 release ", 10),
    'csv' => "title,group,source\nA Movie,GRP,BluRay\nAnother,GRP,WEB-DL\nThird,GRP,HDTV\n",
    'csv two lines' => "title,group,source release video\nA Movie,GRP,BluRay audio codec\n",
    'json' => '{"release": "Some.Movie", "group": "GRP", "source": "BluRay", "video": "x265"}',
    'xml' => '<?xml version="1.0"?><release><group>GRP</group><source>BluRay</source></release>',
    'nzb' => '=newz[NZB]= release group source codec video audio and other words',
    'sfv header' => "; Generated by QuickSFV v2.36\nfile.rar 12345678\nrelease group source video\n",
    'html' => "<html><body><p>Release group source video audio codec subtitles</p></body></html>\n",
    'shell script' => "#!/bin/sh\necho release group source video audio codec subtitle language\n",
    'zip magic' => "PK\x03\x04".$scene,
    'rar magic' => "Rar!\x1a\x07\x00".$scene,
    'png magic' => "\x89PNG\r\n\x1a\n".$scene,
    'mkv magic' => "\x1a\x45\xdf\xa3".$scene,
    'exe magic' => 'MZ'.$scene,
    'riff' => 'RIFF'.$scene,
    'par2' => "PAR2\0PKT".str_repeat("\0", 56).$scene,
    'id3 offset' => 'xx ID3 '.$scene,
    'gzip' => "\x1f\x8b\x08\x00".$scene,
    'utf16 bom only header' => "\xfe\xff".$scene,
    'too big' => str_repeat($scene, 200),
    'leading spaces' => "     \n\n".$scene,
    'bad json' => '{bad json, release group source video audio codec subtitle language}'."\n",
];
mt_srand(1253);
for ($index = 0; $index < 6; $index++) {
    $bytes = '';
    for ($byte = 0; $byte < 400; $byte++) {
        $bytes .= chr(mt_rand(0, 255));
    }
    $samples['random '.$index] = $bytes;
}
foreach (glob(__DIR__.'/archives/*') as $path) {
    $samples['archive '.basename($path)] = substr((string) file_get_contents($path), 0, 4096);
}

$detections = [];
foreach ($samples as $name => $data) {
    $detections[] = [
        'name' => $name,
        'data' => bin2hex($data),
        'magic' => finfo_buffer($finfo, $data),
        'text' => (bool) preg_match($textFile, (string) finfo_buffer($finfo, $data)),
        'validate' => $validate($data),
        'is_nfo' => $isNfo($data),
    ];
}

$parser = new NzbParserService;
$subjects = [
    '"Movie.2160p.nfo" yEnc (1/1)',
    '"Movie.2160p.NFO" yEnc (1/1)',
    '"movie.diz" yEnc (1/1)',
    '"movie.info" yEnc (1/1)',
    '"movie.inf" yEnc (1/1)',
    '"movie.nfo.bak" yEnc (1/1)',
    '"movie.nfo-1" yEnc (1/1)',
    '"readme.txt" yEnc (1/1)',
    '"00-group-release.txt" yEnc (1/1)',
    '"file_id.diz" yEnc (1/1)',
    '"release notes.txt" yEnc (1/1)',
    '"abcdef0123" yEnc (1/1)',
    'abc.def-ghi (1/1)',
    'abc (1/1)',
    '"abc.rar" yEnc (1/1)',
    '"abc.r01" yEnc (1/1)',
    '"abc.mkv" yEnc (1/1)',
    '"abc.srt" yEnc (1/1)',
    '"info" yEnc (1/2)',
    '"readme" yEnc (1/2)',
    'something yEnc (1234) [1/1]',
    '"Movie.2160p.par2" yEnc (1/1)',
    '"Movie.2160p.par2"',
    'Movie.2160p.par2',
    '"Movie.2160p.vol00+01.par2" yEnc (1/3)',
    '[1/20] - "Movie.part01.rar" yEnc (1/50)',
    'Movie [3/7]',
    'Movie (12)',
    'Movie (0/0)',
    'Movie',
    'Movie (1/99999999999999999999)',
];
$subjectChecks = [];
foreach ($subjects as $subject) {
    foreach ([1, 2, 3] as $segments) {
        $subjectChecks[] = [
            'subject' => $subject,
            'segments' => $segments,
            'nfo' => $parser->detectNfoFile($subject),
            'hidden' => $parser->detectHiddenNfoFile($subject, $segments),
        ];
    }
}
$parts = [];
foreach ($subjects as $subject) {
    $parts[] = [
        'subject' => $subject,
        'total' => $parser->extractPartsTotal($subject),
        'par2_index' => $parser->detectPar2IndexFile($subject),
    ];
}

echo json_encode([
    'detections' => $detections,
    'subjects' => $subjectChecks,
    'parts' => $parts,
], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR), "\n";
